{"version":"2b1","blocks":[{"type":"text","text":"The dot product of two vectors measures how much one vector extends in the direction of the other. Geometrically, it equals the product of their lengths and the cosine of the angle between them."},{"type":"ui","source":"root = Stack([definition,diagram,control,result])

angle_deg = 60
$angle = angle_deg

// Convert degrees to radians for cosine
angle_rad = $angle * 3.14159 / 180

// Vector lengths fixed at 1 for simplicity
lengthA = 1
lengthB = 1

// Dot product formula
dot = lengthA * lengthB * cos(angle_rad)

// Projection of A onto B
projection = lengthA * cos(angle_rad)

// Determine orthogonality and sign
isOrthogonal = ($angle == 90) ? 1 : 0
isNegativeProjection = (cos(angle_rad) < 0) ? 1 : 0

// Text explanation
definition = Text("The dot product of vectors A and B equals |A| × |B| × cos(θ), where θ is the angle between them. It represents how much A points in B's direction.")

// Diagram with vectors and angle
// Vector A from origin (50,100) to (50+lengthA*cos(0), 100-lengthA*sin(0)) = (150,100)
// Vector B from origin (50,100) to (50+lengthB*cos(angle_rad), 100-lengthB*sin(angle_rad))
// Coordinates:
Ax = 50
Ay = 100
Bx = 50 + lengthB * 80 * cos(angle_rad)
By = 100 - lengthB * 80 * sin(angle_rad)

// Draw vectors as arrows
vectorA = path("M 50 100 L 130 100")
vectorB = path("M 50 100 L " + Bx + " " + By)

// Angle arc at origin
arcPath = "M 90 100 A 40 40 0 0 1 " + (50 + 40 * cos(angle_rad)) + " " + (100 - 40 * sin(angle_rad))

// Group items
items = [
  path("M 50 100 L 130 100"),
  path("M 50 100 L " + Bx + " " + By),
  path(arcPath),
  text(60, 85, "θ = " + $angle + "°"),
  text(90, 110, "A"),
  text(Bx + 5, By, "B")
]

diagram = Graphic("Vector diagram", items)

// Control to change angle
control = Control("Angle θ (degrees)", 0, 180, [], $angle)

// Result metrics
result = Stack([
  Metric("Dot product = |A||B|cos(θ)", dot),
  Metric("Projection of A on B", projection),
  Metric("Orthogonal (θ=90°)", isOrthogonal),
  Metric("Negative projection (cos(θ)<0)", isNegativeProjection)
])","state":[{"name":"angle","value":60}]}]}

